import {polygon,edges,cuts,mix,distance,cross,sub,on,area,contained} from './geometry.js';
const lineKey=p=>`${p.x.toFixed(6)},${p.y.toFixed(6)}`;
export function validFoundationLines(f){const lines=f.foundationLines??[];return Array.isArray(lines)&&lines.length<=300&&new Set(lines.map(l=>l?.id)).size===lines.length&&lines.every(l=>l&&typeof l.id==='string'&&[l.a?.x,l.a?.y,l.b?.x,l.b?.y].every(n=>Number.isFinite(n)&&Math.abs(n)<=100000)&&distance(l.a,l.b)>=.009999&&distance(l.a,l.b)<=20000);}
export function boundedFaces(lines){const nodes=new Map(),adj=new Map();const node=p=>{const key=lineKey(p);if(!nodes.has(key)){nodes.set(key,{x:Number(p.x.toFixed(6)),y:Number(p.y.toFixed(6))});adj.set(key,new Set())}return key};for(const e of lines){const ts=[0,1,...lines.flatMap(f=>cuts(e.a,e.b,f.a,f.b))].sort((a,b)=>a-b).filter((t,i,a)=>!i||t-a[i-1]>1e-7);for(let i=1;i<ts.length;i++){const a=node(mix(e.a,e.b,ts[i-1])),b=node(mix(e.a,e.b,ts[i]));if(a!==b){adj.get(a).add(b);adj.get(b).add(a)}}}
const queue=[...adj.keys()].filter(k=>adj.get(k).size<2);while(queue.length){const k=queue.pop();if(!adj.has(k)||adj.get(k).size>=2)continue;for(const n of adj.get(k)){adj.get(n).delete(k);if(adj.get(n).size<2)queue.push(n)}adj.delete(k)}const neighbors=new Map([...adj].map(([k,ns])=>[k,[...ns].sort((a,b)=>Math.atan2(nodes.get(a).y-nodes.get(k).y,nodes.get(a).x-nodes.get(k).x)-Math.atan2(nodes.get(b).y-nodes.get(k).y,nodes.get(b).x-nodes.get(k).x))]));const visited=new Set(),faces=[];for(const [start,ns]of neighbors)for(const next of ns){if(visited.has(start+'>'+next))continue;let a=start,b=next,loop=[],closed=false;for(let i=0;i<2400;i++){const key=a+'>'+b;if(visited.has(key)){closed=a===start&&b===next;break}visited.add(key);loop.push(nodes.get(a));const choices=neighbors.get(b),index=choices.indexOf(a),c=choices[(index-1+choices.length)%choices.length];a=b;b=c;}if(!closed||loop.length<3)continue;const signed=loop.reduce((n,p,i)=>n+cross(p,loop[(i+1)%loop.length]),0)/2;if(signed<=1e-6)continue;let changed=true;while(changed&&loop.length>3){changed=false;loop=loop.filter((p,i)=>{const a=loop[(i-1+loop.length)%loop.length],b=loop[(i+1)%loop.length];if(Math.abs(cross(sub(p,a),sub(b,p)))<1e-7&&on(p,a,b)){changed=true;return false}return true})}if(new Set(loop.map(lineKey)).size===loop.length)faces.push(loop);}return faces;}
export function shapeFromFace(points,id,name){const minX=Math.min(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),w=Math.max(...points.map(p=>p.x))-minX,h=Math.max(...points.map(p=>p.y))-minY;if(w<.01||h<.01||points.length>128)return null;return {id,name,layer:'foundation',type:'polygon',x:minX,y:minY,w,h,rotation:0,points:points.map(p=>[Math.max(0,Math.min(1,(p.x-minX)/w)),Math.max(0,Math.min(1,(p.y-minY)/h))])};}
export function fillLinework(drafts,foundations,makeId=()=>crypto.randomUUID()){const boundary=foundations.flatMap(o=>edges(polygon(o))),faces=boundedFaces([...drafts,...boundary]),shapes=[],filled=[];let skipped=0;for(const points of faces){const candidate=shapeFromFace(points,makeId(),'Foundation '+(foundations.length+shapes.length+1));if(!candidate){skipped++;continue}if(!contained(candidate,[...foundations,...shapes]))shapes.push(candidate);filled.push(points);}const faceEdges=filled.flatMap(edges),remaining=[];for(const e of drafts){const ts=[0,1,...faceEdges.flatMap(f=>cuts(e.a,e.b,f.a,f.b))].sort((a,b)=>a-b).filter((t,i,a)=>!i||t-a[i-1]>1e-7);for(let i=1;i<ts.length;i++){const a=mix(e.a,e.b,ts[i-1]),b=mix(e.a,e.b,ts[i]),mid=mix(a,b,.5);if(distance(a,b)>=.01&&!faceEdges.some(f=>on(mid,f.a,f.b)))remaining.push({id:makeId(),a,b});}}return {shapes,lines:remaining,closed:remaining.reduce((n,l)=>n+distance(l.a,l.b),0)<drafts.reduce((n,l)=>n+distance(l.a,l.b),0)-1e-5,skipped};}
